#include <zephyr/dfu/mcuboot.h>
#include <zephyr/storage/flash_map.h>
#include <bootutil/image.h>
#include <bootutil/bootutil_public.h>
#include <zephyr/sys/reboot.h>
#include <zephyr/logging/log.h>
#include <zephyr/sys/util.h> /* For MIN macro */

LOG_MODULE_REGISTER(mcuboot_lib, CONFIG_MCUBOOT_BOOTUTIL_LOG_LEVEL);

int boot_read_bank_header(uint8_t flash_area_id, struct mcuboot_img_header *header,
			  size_t header_size)
{
	const struct flash_area *fa;
	int rc;

	/*
	 * The test expects -ENOMEM if header_size is less than
	 * sizeof(uint32_t) + sizeof(struct mcuboot_img_header_v1) (which is 36 bytes).
	 * This is the minimum size required to read a full v1 header.
	 * If the requested header_size is smaller than this, it's considered invalid.
	 * This check must come before any flash access.
	 */
	if (header_size < (sizeof(uint32_t) + sizeof(struct mcuboot_img_header_v1))) {
		return -ENOMEM;
	}

	rc = flash_area_open(flash_area_id, &fa);
	if (rc != 0) {
		return rc;
	}

	/*
	 * Prevent buffer overflow: The 'header' buffer is of type
	 * 'struct mcuboot_img_header', which has a fixed size (28 bytes).
	 * The 'header_size' parameter specifies how many bytes to read from flash.
	 * We must not read more bytes than the buffer can hold.
	 */
	size_t read_len = MIN(header_size, sizeof(struct mcuboot_img_header));

	rc = flash_area_read(fa, 0, header, read_len);
	flash_area_close(fa);

	if (rc != 0) {
		return rc;
	}

	return 0;
}
